import eslintConfigNext from "eslint-config-next";
import simpleImportSort from "eslint-plugin-simple-import-sort";
import unusedImports from "eslint-plugin-unused-imports";

const config = [
  {
    // Agent worktrees under .claude/ are full checkouts of this repo, so
    // linting them re-reports every file against whatever branch they hold.
    // coverage/ is generated by `vitest --coverage`; it belongs here rather than
    // as a --ignore-pattern flag in the package scripts, so a bare `pnpm exec eslint .`
    // and editor integrations honour it too. The e2e suite's artifacts/ is
    // generated too: a failing test's HTML report bundles Playwright's
    // minified trace viewer there. design-sync's staged converter, bundle
    // output and emitted declarations are gitignored build products too.
    ignores: [
      ".claude/**",
      ".next/**",
      "coverage/**",
      "e2e/series-finale/artifacts/**",
      ".ds-sync/**",
      "ds-bundle/**",
      "dist/types/**",
    ],
  },
  ...eslintConfigNext,
  {
    plugins: {
      "simple-import-sort": simpleImportSort,
      "unused-imports": unusedImports,
    },
    rules: {
      "simple-import-sort/imports": "error",
      "simple-import-sort/exports": "error",
      "import/no-duplicates": "error",
      "no-unused-vars": "off",
      "unused-imports/no-unused-imports": "error",
      "unused-imports/no-unused-vars": [
        "warn",
        {
          vars: "all",
          varsIgnorePattern: "^_",
          args: "after-used",
          argsIgnorePattern: "^_",
        },
      ],
    },
  },
  {
    // Scoped to TypeScript files because that is where eslint-config-next
    // registers the @typescript-eslint plugin; referencing the rule for .mjs
    // config files, where the plugin is absent, is a configuration error.
    files: ["**/*.ts", "**/*.tsx"],
    rules: {
      "@typescript-eslint/no-explicit-any": "error",
    },
  },
  {
    files: ["**/*.test.tsx", "**/*.test.ts"],
    rules: {
      "@next/next/no-img-element": "off",
      // The DB and fetch doubles lean on `(db as any)` and friends throughout;
      // there are ~800 occurrences across the suites. `lint:ci` runs with
      // --max-warnings=0, so this has to be off rather than a warning. The rule
      // is enabled for production code above, which is where it buys something.
      "@typescript-eslint/no-explicit-any": "off",
    },
  },
  {
    // useProgressRouter starts the top-of-page navigation bar on push and
    // replace; a bare useRouter navigates without it.
    files: ["src/**/*.ts", "src/**/*.tsx"],
    ignores: ["src/hooks/useProgressRouter.ts", "**/*.test.ts", "**/*.test.tsx"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          paths: [
            {
              name: "next/navigation",
              importNames: ["useRouter"],
              message:
                "Use useProgressRouter from @/hooks/useProgressRouter, so navigation shows the progress bar.",
            },
          ],
        },
      ],
    },
  },
  {
    // Contracts and client code ship to the browser. A runtime import of Zod or
    // a feature's schemas.ts adds about 55 KB gzipped to run validators the
    // client never calls, and tree-shaking does not remove it (zod/mini included).
    // `import type` is erased, so it stays allowed. @/lib/db/schema is allowed
    // because components already import its enums.
    files: [
      "src/lib/**/contract.ts",
      "src/lib/api/client.ts",
      "src/lib/api/errors.ts",
      "src/components/**/*.{ts,tsx}",
      "src/hooks/**/*.{ts,tsx}",
    ],
    ignores: ["**/*.test.ts", "**/*.test.tsx"],
    rules: {
      "@typescript-eslint/no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              regex: "^zod(/|$)|(^|/)schemas$",
              allowTypeImports: true,
              message:
                "Schemas are server-only. Use `import type` so Zod stays out of the client bundle.",
            },
          ],
        },
      ],
    },
  },
  {
    // A contract is imported by client code, so it must not reach server modules.
    files: ["src/lib/**/contract.ts"],
    ignores: ["**/*.test.ts"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          paths: [
            {
              name: "next/navigation",
              importNames: ["useRouter"],
              message:
                "Use useProgressRouter from @/hooks/useProgressRouter, so navigation shows the progress bar.",
            },
            { name: "next/server", message: "Contracts are client-safe." },
          ],
          patterns: [
            {
              regex: "(^|/)(db|service)$|^@/lib/auth/(webauthn|api-middleware)$",
              message: "Contracts are client-safe; this module is server-only.",
            },
          ],
        },
      ],
    },
  },
  {
    // share-card.tsx is drawn by Satori (next/og), which knows plain <img>
    // and nothing of next/image. BrandLogo renders data-URI marks inside the
    // standalone design-sync bundle, where next/image's loader is unavailable.
    files: [
      ".design-sync/brand/BrandLogo.tsx",
      "src/components/ui/QRCode.tsx",
      "src/lib/series-finale/share-card.tsx",
    ],
    rules: {
      "@next/next/no-img-element": "off",
    },
  },
  {
    // Verified live, not a blanket disable: unexempting this file produces two
    // real react-hooks/set-state-in-effect errors. useFragmentNavigation.ts was
    // also listed here and did not need it -- its only setState runs inside a
    // popstate handler, not in an effect body.
    files: ["src/components/profile/StreamingPreferences.tsx"],
    rules: {
      "react-hooks/set-state-in-effect": "off",
    },
  },
];

export default config;
